import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Components & Props', () => {
  test('Renders two UserCard components', async () => {
    const { container: root } = render(<App />);
    const cards = root.querySelectorAll('.user-card');
if (cards.length !== 2) throw new Error('Expected 2 elements with class "user-card", found ' + cards.length);
  });

  test('First card shows "Alice" and "Developer"', async () => {
    const { container: root } = render(<App />);
    const cards = root.querySelectorAll('.user-card');
const first = cards[0];
if (!first) throw new Error('No user-card found');
if (!first.querySelector('h2')?.textContent.includes('Alice'))
  throw new Error('First card h2 should contain "Alice"');
if (!first.querySelector('p')?.textContent.includes('Developer'))
  throw new Error('First card p should contain "Developer"');
  });

  test('Second card shows "Bob" and "Designer"', async () => {
    const { container: root } = render(<App />);
    const cards = root.querySelectorAll('.user-card');
const second = cards[1];
if (!second) throw new Error('Second user-card not found');
if (!second.querySelector('h2')?.textContent.includes('Bob'))
  throw new Error('Second card h2 should contain "Bob"');
if (!second.querySelector('p')?.textContent.includes('Designer'))
  throw new Error('Second card p should contain "Designer"');
  });

  test('Each card has an <h2> and <p> inside a div', async () => {
    const { container: root } = render(<App />);
    const cards = root.querySelectorAll('.user-card');
cards.forEach((card, i) => {
  if (card.tagName !== 'DIV') throw new Error('Card ' + (i+1) + ' should be a <div>');
  if (!card.querySelector('h2')) throw new Error('Card ' + (i+1) + ' missing <h2>');
  if (!card.querySelector('p')) throw new Error('Card ' + (i+1) + ' missing <p>');
});
  });
});
